.ds-meridian { --ds-cover-bg: var(--ds-canvas); --ds-hand-ink: var(--ds-ink-faint); --ds-hand-fill: var(--ds-blue); --ds-hand-fill2: var(--ds-blue); --ds-hand-muted: var(--ds-surface-sunk); --ds-hand-ground: var(--ds-surface); --ds-hand-stroke: 1.5; --ds-hand-cap: round; --ds-hand-bg: var(--ds-canvas); --ds-hand-text-stroke: var(--ds-surface);
