.ds-meridian .ds-principle-n { color: var(--ds-ink-faint); font-weight: 500; }
.ds-meridian .ds-comp, .ds-meridian .ds-motif, .ds-meridian .ds-note, .ds-meridian .ds-voice, .ds-meridian .ds-hand-panel, .ds-meridian .ds-tpl, .ds-meridian .ds-tpl-kpi, .ds-meridian .ds-tpl-tile, .ds-meridian .ds-tpl-step, .ds-meridian .ds-tpl-wire, .ds-meridian .ds-tpl-flow, .ds-meridian .ds-tpl-stage { border-color: var(--ds-hairline); box-shadow: var(--ds-shadow-tile); }
