.ds-meridian .me-dot-ok { fill: var(--ds-positive); } .ds-meridian .me-dot-warn { fill: var(--ds-caution); } .ds-meridian .me-dot-bad { fill: var(--ds-negative); } .ds-meridian .me-dot-ring { opacity: .25; }
