.ds-meridian .me-btn-danger { color: var(--ds-negative); } .ds-meridian .me-btn-danger:hover { background: var(--ds-negative); border-color: var(--ds-negative); color: var(--ds-on-blue); }
.ds-meridian .me-tag { display: inline-flex; align-items: center; gap: 6px; padding: 2px 10px 2px 8px; border-radius: 999px; font-size: 12px; font-weight: 500; line-height: 18px; background: var(--ds-surface-sunk); color: var(--ds-ink-soft); }
.ds-meridian .me-tag i { position: relative; width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
