.ds-meridian .me-metric-row { display: grid; grid-template-columns: 110px 1fr auto; gap: 12px; align-items: center; padding: 8px 0; border-top: 1px solid var(--ds-hairline); font-size: 13px; color: var(--ds-ink-soft); }
