.ds-meridian .me-avatar { width: 26px; height: 26px; border-radius: 50%; background: var(--ds-blue-soft); border: 1px solid var(--ds-hairline-strong); } .ds-meridian .me-avatar-ini { display: inline-flex; align-items: center; justify-content: center; font-size: 10px; font-weight: 600; color: var(--ds-blue-ink); }
