.ds-meridian .me-table th, .ds-meridian .me-table td { border-left: 0; border-right: 0; border-top: 0; background: transparent; text-align: left; padding: 7px 8px; border-bottom: 1px solid var(--ds-hairline); white-space: nowrap; }
