.ds-meridian .me-table th:first-child, .ds-meridian .me-table td:first-child { padding-left: 8px; } .ds-meridian .me-table tbody tr:hover td { background: var(--ds-surface-sunk); }
.ds-meridian .me-table .me-r { text-align: right; font-variant-numeric: tabular-nums; } .ds-meridian .me-table .me-mono { font-family: var(--font-mono); font-size: 12px; color: var(--ds-ink-soft); }
.ds-meridian .me-cust { display: inline-grid; vertical-align: middle; line-height: 1.2; } .ds-meridian .me-cust small { font-family: var(--font-mono); font-size: 11px; color: var(--ds-ink-faint); }
.ds-meridian .me-ini { display: inline-flex; align-items: center; justify-content: center; width: 22px; height: 22px; margin-right: 8px; border-radius: 6px; background: var(--ds-surface-sunk); border: 1px solid var(--ds-hairline); font-size: 10px; font-weight: 600; color: var(--ds-ink-soft); vertical-align: middle; }
.ds-meridian .me-dot-tag { display: inline-flex; align-items: center; gap: 6px; font-weight: 500; color: var(--ds-ink-soft); } .ds-meridian .me-dot-tag i { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
.ds-meridian .me-dt-ok { color: var(--ds-positive); } .ds-meridian .me-dt-warn { color: var(--ds-caution); } .ds-meridian .me-dt-bad { color: var(--ds-negative); }
.ds-meridian .me-activity { padding: 16px 20px 32px; border-top: 1px solid var(--ds-hairline); background: var(--ds-surface); }
.ds-meridian .me-act-h { margin: 0 0 8px; color: var(--ds-ink-faint); }
.ds-meridian .me-act { display: grid; grid-template-columns: 14px 1fr; gap: 10px; padding: 10px 0; border-top: 1px solid var(--ds-hairline); font-size: 13px; } .ds-meridian .me-act div { display: grid; gap: 2px; } .ds-meridian .me-act-t { font-size: 12px; color: var(--ds-ink-faint); }
.ds-meridian .me-act-dot { width: 8px; height: 8px; margin-top: 5px; border-radius: 50%; background: var(--ds-hairline-strong); } .ds-meridian .me-act-ok { background: var(--ds-positive); } .ds-meridian .me-act-bad { background: var(--ds-negative); } .ds-meridian .me-act-blue { background: var(--ds-blue); }
@container (min-width: 760px) {
  .ds-meridian .me-shell { grid-template-columns: 200px minmax(0, 1fr); }
  .ds-meridian .me-rail { flex-direction: column; align-items: stretch; gap: 0; padding: 16px 12px; border-bottom: 0; border-right: 1px solid var(--ds-hairline); overflow: visible; min-height: 100%; }
