}
@container (min-width: 1100px) {
  .ds-meridian .me-shell { grid-template-columns: 200px minmax(0, 1fr) 240px; }
  .ds-meridian .me-activity { grid-column: auto; display: block; border-top: 0; border-left: 1px solid var(--ds-hairline); padding: 16px 20px 32px; }
  .ds-meridian .me-sample-grid { grid-template-columns: 3fr 2fr; }
}
